34	        int lastSelectedFinish = activities[0].finishTime();
35	
36	        for (int i = 1; i < activities.length; i++) {
37	            Activity candidate = activities[i];
38	            if (candidate.startTime() >= lastSelectedFinish) {
39	                selectedCount++;
40	                lastSelectedFinish = candidate.finishTime();
41	            }
42	        }
43	
44	        return selectedCount;
45	    }
